 {id:'camera',label:'Camera',icon:'◉',cls:'camera'}, {id:'weather',label:'Weather',icon:'☀',cls:'weather'}, {id:'notes',label:'Notes',icon:'▤',cls:'notes'}, {id:'calendar',label:'Calendar',icon:'17',cls:'calendar'},
 {id:'music',label:'Music',icon:'♫',cls:'music'}, {id:'clock',label:'Clock',icon:'◷',cls:'clock'}, {id:'mail',label:'Mail',icon:'✉',cls:'mail'}, {id:'settings',label:'Settings',icon:'⚙',cls:'settings'},
 {id:'phone',label:'Phone',icon:'⌕',cls:'phone'}, {id:'store',label:'App Store',icon:'A',cls:'store'}, {id:'podcasts',label:'Podcasts',icon:'◉',cls:'podcasts'}, {id:'tips',label:'Tips',icon:'✦',cls:'tips'}
];
const missionData=[
 {title:'Find the hidden signal',desc:'Open Safari on Blue and search for “the signal”.',hint:'HINT: THE WEB IS FULL OF CLUES'},
 {title:'Meet at Moonbean Café',desc:'Link the phones, then find Moonbean Café in Pink Maps.',hint:'HINT: ONE CLUE LEADS TO THE NEXT'},
 {title:'Send the meetup code',desc:'Use Blue Messages to send “moonlight” to your partner.',hint:'HINT: THE BEST CLUES ARE SHARED'}
];
function iconsMarkup(phone){return apps.map(a=>`<button class="app-icon" data-open="${a.id}" data-phone="${phone}" aria-label="Open ${a.label}"><span class="icon-tile icon-${a.cls}">${a.icon}</span><span class="app-label">${a.label}</span></button>`).join('')}
function home(phone){return `<div class="home-view"><div class="date-line">TUESDAY, JUNE 17</div><div class="home-greeting">Good morning<span>, ${phone==='blue'?'Ari':'Sam'}.</span></div><div class="widget-row"><div class="widget"><span class="weather-icon">${phone==='blue'?'☀':'⛅'}</span><div class="weather-temp">${phone==='blue'?'21°':'19°'}</div><div class="weather-city">${phone==='blue'?'Brooklyn':'Brooklyn'} · ${phone==='blue'?'Sunny':'Breezy'}</div></div><div class="widget calendar-widget"><div><div class="cal-day">JUN</div><div class="cal-num">17</div></div><div><div class="cal-event">${phone==='blue'?'A new adventure':'Meet me soon?'}</div><div class="cal-event">${state.connected?'✦ linked':'No plans yet'}</div></div></div></div><div class="app-grid">${iconsMarkup(phone)}</div><div class="dock">${['phone','safari','messages','music'].map(id=>{const a=apps.find(x=>x.id===id);return `<button class="app-icon" data-open="${a.id}" data-phone="${phone}" aria-label="Open ${a.label}"><span class="icon-tile icon-${a.cls}">${a.icon}</span></button>`}).join('')}</div><div class="page-dots"><i></i><i></i></div></div>`}
function nav(title,phone,action=''){return `<div class="app-nav"><button class="app-back" data-home="${phone}">‹ Home</button><span class="tiny muted">${phone==='blue'?'BLUE':'PINK'}</span><button class="app-action" ${action}>${title==='Safari'?'Aa':'···'}</button></div><div class="app-title">${title}</div>`}
function messages(phone){return `${nav('Messages',phone)}<div class="app-scroll"><div class="chat-name">● Ari &amp; Sam ${state.connected?'<span class="pill">LINKED</span>':''}</div><div id="chat-list">${state.messages.map(m=>`<div class="message-bubble ${m.from===(phone==='blue'?'Blue':'Pink')?'mine':''}">${esc(m.text)}<div class="tiny" style="opacity:.65;margin-top:3px">${m.from} · ${m.time}</div></div>`).join('')}</div></div><form class="chat-compose" data-form="message" data-phone="${phone}"><input class="text-input" name="message" placeholder="iMessage" autocomplete="off"/><button class="round-send" aria-label="Send">↑</button></form>`}
function safari(phone){let q=state.query[phone];let content=q?searchResults(phone,q):`<div class="panel tiny"><span style="font-size:20px">🌐</span><div style="font:600 13px 'Space Grotesk';margin-top:5px">The little internet</div><div class="muted" style="margin-top:4px">Big discoveries, one search away.</div></div><div class="section-title">QUICK LINKS</div><div class="panel"><div class="list-row web-link" data-query="the signal"><span>✦ &nbsp; Signal &amp; Noise</span><span>↗</span></div><div class="list-row web-link" data-query="Moonbean Cafe"><span>☕ &nbsp; City Guide</span><span>↗</span></div><div class="list-row web-link" data-query="space"><span>◉ &nbsp; Pocket Astronomy</span><span>↗</span></div></div><div class="panel tiny muted">A playful, built-in browser. Search the web of Duo City.</div>`;return `${nav('Safari',phone)}<div class="browser-bar"><span>🔒 &nbsp; duocity.local</span><button data-browser-refresh aria-label="Refresh">↻</button></div><form class="search-form" data-form="search" data-phone="${phone}" style="display:flex;gap:6px;margin-top:7px"><input class="text-input" name="query" value="${esc(q)}" placeholder="Search or enter a website" autocomplete="off"/><button class="round-send" aria-label="Search">⌕</button></form><div class="app-scroll">${content}</div>`}
function searchResults(phone,q){let t=q.toLowerCase();if(t.includes('signal')){return `<div class="web-hero"><small>DUO CITY OBSERVER · FIELD NOTE 07</small><h3>The signal is<br/>a little closer.</h3><p>We found a curious transmission near the old observatory. Clue: <b>LOOK FOR THE BLUE DOT</b>.</p></div><div class="section-title">SEARCH RESULTS</div><div class="panel tiny"><b>Signal &amp; Noise</b><div class="muted" style="margin-top:5px">A neighborhood guide to curious things, secret places, and the people who find them.</div></div><button class="primary-button" data-result="signal">Save clue to ${phone==='blue'?'Blue':'Pink'}</button>${state.quest===0&&phone==='blue'?'<div class="panel tiny" style="text-align:center;color:#e5ffad">✦ You found the hidden signal!</div>':''}`}
if(t.includes('moonbean')||t.includes('cafe')||t.includes('café'))return `<div class="web-hero" style="background:linear-gradient(140deg,#c7e9bc,#76baa5);color:#163d34"><small>DUO CITY GUIDE · BROOKLYN</small><h3>Moonbean<br/>Café ☕</h3><p>Small batch coffee, big-window seats, and the best cinnamon buns on this side of the river.</p></div><div class="panel"><div style="font:600 11px 'Space Grotesk'">Moonbean Café</div><div class="tiny muted" style="margin-top:5px">📍 17 Orchard Lane · Open until 6 pm</div><div class="tiny" style="margin-top:5px">★★★★★ &nbsp; 4.9 · 128 happy sippers</div><button class="primary-button" data-directions="moonbean">Get directions in Maps ↗</button></div>`;
if(t.includes('space'))return `<div class="web-hero" style="background:linear-gradient(140deg,#aeb4ff,#6a6fca);color:#181d53"><small>POCKET ASTRONOMY · TONIGHT</small><h3>Look up.<br/>The sky is yours.</h3><p>Tonight: Jupiter makes a close pass by the crescent moon. Best viewing after 9:15 pm.</p></div><div class="panel tiny">✦ <b>Stargazer's tip</b><div class="muted" style="margin-top:5px">Find a dark spot, give your eyes ten minutes, and leave the telescope at home.</div></div>`;
return `<div class="web-hero"><small>DUO CITY WEB</small><h3>You're exploring.</h3><p>Try “the signal”, “Moonbean Cafe”, or “space” to find something interesting.</p></div><div class="section-title">YOU MIGHT LIKE</div><div class="panel"><div class="list-row web-link" data-query="the signal">✦ &nbsp; Signal &amp; Noise</div><div class="list-row web-link" data-query="Moonbean Cafe">☕ &nbsp; Moonbean Café</div><div class="list-row web-link" data-query="space">◉ &nbsp; Pocket Astronomy</div></div>`}
function maps(phone){return `${nav('Maps',phone)}<div class="app-scroll"><div class="map-panel"><span class="map-river"></span><span class="map-road"></span><span class="map-route"></span><span class="map-place">📍</span><span class="map-label" style="top:20%;left:10%">ORCHARD ST</span><span class="map-label" style="top:72%;left:55%">BROOKLYN</span><span class="map-label" style="top:58%;left:5%">RIVER WALK</span></div><form class="search-form map-search" data-form="map" data-phone="${phone}"><input class="text-input" name="place" value="${phone==='pink'&&state.query.pink==='Moonbean Café'?'Moonbean Café':''}" placeholder="Search places" autocomplete="off"/></form><div id="map-result">${state.quest>=1?`<div class="panel"><div style="font:600 12px 'Space Grotesk'">☕ Moonbean Café</div><div class="tiny muted" style="margin-top:5px">17 Orchard Lane · 12 min walk</div><div class="tiny" style="margin-top:6px">↗ Head north on Orchard St</div>${state.quest===1&&phone==='pink'?'<div style="color:#e5ffad;font-size:9px;margin-top:8px">✦ Destination found!</div>':''}</div>`:`<div class="panel tiny muted" style="text-align:center">Find a place to get started.</div>`}</div><div class="section-title">NEARBY</div><div class="panel"><div class="list-row"><span>☕ &nbsp; Coffee &amp; tea</span><span class="muted">6</span></div><div class="list-row"><span>🌳 &nbsp; Parks</span><span class="muted">3</span></div><div class="list-row"><span>✦ &nbsp; Hidden spots</span><span class="muted">?</span></div></div></div>`}
function photos(phone){return `${nav('Photos',phone)}<div class="app-scroll"><div class="section-title">RECENT MEMORIES</div><div class="photo-grid"><div class="photo" style="background:linear-gradient(140deg,#ffbe76,#d36658)">🌅<span>Golden hour</span></div><div class="photo" style="background:linear-gradient(140deg,#9ed4df,#437ba0)">🌊<span>By the river</span></div><div class="photo" style="background:linear-gradient(140deg,#a4c985,#418870)">🌿<span>Sunday stroll</span></div><div class="photo" style="background:linear-gradient(140deg,#aa89cb,#e4a0ba)">🌸<span>Bloom season</span></div>${state.captured?`<div class="photo" style="background:linear-gradient(140deg,#718fb7,#d7a984)">📸<span>New photo</span></div>`:''}</div><div class="section-title">SHARED ALBUM</div><div class="panel tiny">${state.connected?'✦ &nbsp; Ari & Sam · '+(4+state.captured)+' photos':'Link the phones to see shared memories.'}</div></div>`}
function music(phone){return `${nav('Music',phone)}<div class="app-scroll"><div class="music-art">${state.playing?'🎶':'🌙'}</div><div style="text-align:center;margin-top:12px;font:600 15px 'Space Grotesk'">${state.playing?'Side by Side':'Soft Focus'}</div><div style="text-align:center;font-size:9px;color:#ffffff9a;margin-top:4px">${state.playing?'The Duo Sessions':'Luna Park'}</div><div class="music-progress"><i style="width:${state.playing?'57%':'32%'}"></i></div><div class="music-times"><span>1:24</span><span>3:48</span></div><div class="music-controls"><button data-music="prev">↶</button><button class="play" data-music="toggle">${state.playing?'Ⅱ':'▶'}</button><button data-music="next">↷</button></div><div class="panel tiny">♫ &nbsp; Now playing on ${phone==='blue'?'Blue':'Pink'}${state.connected?' · synced with your partner':''}</div></div>`}
function notes(phone){return `${nav('Notes',phone)}<div class="app-scroll"><div class="tiny muted" style="margin:2px 3px 8px">Today, 9:41 AM · ${state.connected?'Shared note':'On my iPhone'}</div><div class="note-paper" contenteditable="true" data-note="${phone}" spellcheck="false">${esc(state.note[phone])}</div><div class="panel tiny">✦ &nbsp; Tap anywhere to edit. Your note saves as you type.</div></div>`}
function camera(phone){return `${nav('Camera',phone)}<div class="app-scroll"><div class="camera-view"><span>${state.captured?'PHOTO SAVED ✓':'PORTRAIT · 1×'}</span></div><button class="shutter" data-camera="${phone}" aria-label="Take photo"></button><div class="tiny muted" style="text-align:center;margin-top:8px">Tap to capture a little memory</div><div class="panel tiny">${state.captured?'You have '+state.captured+' new photo'+(state.captured===1?'':'s')+'. Check Photos!':'Your camera is ready.'}</div></div>`}
function settings(phone){return `${nav('Settings',phone)}<div class="app-scroll"><div class="panel"><div class="list-row"><span>✈ &nbsp; Airplane Mode</span><input type="checkbox" class="setting-toggle"/></div><div class="list-row"><span>◔ &nbsp; Wi-Fi</span><span class="pill">DuoNet</span></div><div class="list-row"><span>☾ &nbsp; Focus</span><input type="checkbox" class="setting-toggle" checked/></div></div><div class="section-title">YOUR DEVICE</div><div class="panel"><div class="list-row"><span>About</span><span class="muted">Duo Phone · 17.0 ›</span></div><div class="list-row"><span>Battery</span><span class="muted">100% ›</span></div><div class="list-row"><span>Wallpaper</span><span class="muted">${phone==='blue'?'Blue Hour':'Pink Dusk'} ›</span></div></div><div class="section-title">GAME SETTINGS</div><div class="panel"><div class="list-row"><span>Co-op link</span><span class="pill">${state.connected?'CONNECTED':'READY'}</span></div><div class="list-row"><span>Quest progress</span><span class="muted">${state.quest}/3 ›</span></div></div></div>`}
function calendar(phone){return `${nav('Calendar',phone)}<div class="app-scroll"><div class="panel" style="text-align:center"><div class="tiny muted">JUNE 2026</div><div class="calendar-large" style="margin-top:10px">${['S','M','T','W','T','F','S'].map(x=>`<span class="day">${x}</span>`).join('')}${Array.from({length:35},(_,i)=>{let n=i-0;return `<span class="${n===17?'today':''}" style="${n>30?'opacity:.3':''}">${n<=30?n+1:n-30}</span>`}).join('')}</div></div><div class="section-title">UP NEXT</div><div class="panel"><div class="list-row"><span><b>✦</b> &nbsp;${state.quest>=2?'Meet at Moonbean Café':'A pocket adventure'}</span><span class="muted">Today · 10:00</span></div><div class="list-row"><span>☕ &nbsp; Coffee with ${phone==='blue'?'Sam':'Ari'}</span><span class="muted">Soon</span></div></div></div>`}
function phoneApp(phone){return `${nav('Phone',phone)}<div class="app-scroll"><div class="call-display"><div class="call-avatar">${phone==='blue'?'🧑🏻':'🧑🏽'}</div><h3>${phone==='blue'?'Sam':'Ari'}</h3><div class="tiny muted">${state.connected?'Duo call available':'Connect the phones for a call'}</div></div><div class="panel"><div class="list-row"><span>◷ &nbsp; Sam · mobile</span><span class="muted">Today</span></div><div class="list-row"><span>◷ &nbsp; Ari · mobile</span><span class="muted">Yesterday</span></div></div><div class="call-buttons"><button>⌨</button><button class="hangup" data-call>☎</button><button>◖</button></div><div class="tiny muted" style="text-align:center">${state.calling?'Calling… (just kidding, this is a game!)':'Tap the green-world call button to try it'}</div></div>`}
function simpleApp(id,phone){let data={weather:['Weather','21°','Sunny skies all day. A perfect day for exploring. ☀'],clock:['Clock','09:41','World clock · Brooklyn, New York'],mail:['Mail','Inbox','Welcome to Duo Mail!\n\nYour inbox is peaceful. Enjoy your adventure.'],store:['App Store','Discover','Apps that make a little world feel big.\n\n✦ Duo City Guide is already installed.'],podcasts:['Podcasts','Listen Now','The Little Things — stories from your neighborhood.\n\n▶ &nbsp; Episode 17: The hidden signal'],tips:['Tips','A tip for you','Did you know? You can link your two phones to share discoveries and messages. ✦']}[id];return `${nav(data[0],phone)}<div class="app-scroll"><div class="web-hero" style="background:linear-gradient(140deg,#b5d8ff,#858ad5);color:#172146"><small>${data[0].toUpperCase()} · DUO PHONE</small><h3>${data[1]}</h3><p>${data[2]}</p></div>${id==='weather'?'<div class="panel"><div class="list-row"><span>UV index</span><span class="pill">Low</span></div><div class="list-row"><span>Feels like</span><span>22°</span></div><div class="list-row"><span>Sunset</span><span>8:24 PM</span></div></div>':id==='mail'?'<div class="panel tiny"><b>From: Duo City</b><div class="muted" style="margin-top:6px">Welcome to the neighborhood. There’s a signal waiting to be found…</div></div>':id==='tips'?'<div class="panel tiny">Try opening Safari, Maps, and Messages to complete your co-op quest. Every app does something!</div>':''}</div>`}
function render(phone){const content=$(`#content-${phone}`);let app=state.opened[phone];content.innerHTML=app?`<div class="app-view">${({messages:()=>messages(phone),safari:()=>safari(phone),maps:()=>maps(phone),photos:()=>photos(phone),music:()=>music(phone),notes:()=>notes(phone),camera:()=>camera(phone),settings:()=>settings(phone),calendar:()=>calendar(phone),phone:()=>phoneApp(phone)})[app]?.()||simpleApp(app,phone)}</div>`:home(phone);}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let toastTimer;function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function questComplete(index,msg){if(state.quest!==index)return;state.quest++;state.xp+=120;updateQuest();toast(msg+'  +120 XP');confetti();}
function updateQuest(){let current=missionData[Math.min(state.quest,2)];$('#questCount').textContent=state.quest===3?'03 / 03':`0${state.quest+1} / 03`;$('#missionTitle').textContent=state.quest===3?'Adventure complete!':current.title;$('#missionDesc').textContent=state.quest===3?'You found the signal, the café, and each other. Nice teamwork.':current.desc;$('#missionHint').textContent=state.quest===3?'✦ BOTH PHONES, ONE GREAT STORY':current.hint;$('#questProgress').style.width=`${state.quest/3*100}%`;$('#xpTotal').textContent=state.xp;$('#footerMessage').textContent=state.quest===3?'ALL QUESTS COMPLETE · YOU MAKE A GREAT TEAM':'YOUR STORY IS JUST GETTING STARTED';if(state.quest===3){$('#missionCard').classList.add('complete');toast('Quest complete! You’re a Duo dream team ✦')}}
function confetti(){let colors=['#d9ff84','#ff9daf','#8ebeff','#fff'];for(let i=0;i<18;i++){let el=document.createElement('i');el.style.cssText=`position:fixed;z-index:50;left:${42+Math.random()*16}%;top:43%;width:6px;height:6px;background:${colors[i%4]};border-radius:${i%2?'50%':'1px'};pointer-events:none;transition:transform .9s,opacity .9s`;document.body.append(el);requestAnimationFrame(()=>{el.style.transform=`translate(${(Math.random()-.5)*300}px,${Math.random()*300+50}px) rotate(${Math.random()*500}deg)`;el.style.opacity=0});setTimeout(()=>el.remove(),1000)}}
function link(){state.connected=!state.connected;document.querySelector('.between').classList.toggle('connected',state.connected);$('#syncLabel').textContent=state.connected?'PHONES CONNECTED':'NOT CONNECTED';$('#syncButton').innerHTML=state.connected?'<span>✓</span> UNLINK PHONES':'<span>↔</span> LINK PHONES';toast(state.connected?'Phones linked! Clues can travel now.':'Phones unlinked.');render('blue');render('pink');if(state.connected&&state.quest===1)toast('Phones linked! Find Moonbean Café in Pink Maps.');}
function openApp(phone,id){state.opened[phone]=id;render(phone)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.open)openApp(b.dataset.phone,b.dataset.open);if(b.dataset.home){state.opened[b.dataset.home]='';render(b.dataset.home)}if(b.dataset.query){state.opened[findPhone(b)]= 'safari';let p=findPhone(b);state.query[p]=b.dataset.query;render(p)}if(b.dataset.result==='signal'&&state.quest===0){questComplete(0,'Signal found!');render(findPhone(b))}if(b.dataset.directions){let phone=findPhone(b);state.query[phone]='Moonbean Café';openApp(phone,'maps');if(state.connected&&state.quest===1&&phone==='pink'){setTimeout(()=>questComplete(1,'Moonbean found!'),120)}}if(b.dataset.music){state.playing=!state.playing;render(findPhone(b))}if(b.dataset.camera){state.captured++;render(b.dataset.camera);toast('Photo saved to Photos!')}if(b.dataset.call){state.calling=true;render(findPhone(b));setTimeout(()=>{state.calling=false;render(findPhone(b))},1700);toast('Calling your partner…')}if(b.id==='syncButton')link();if(b.id==='soundToggle'){const on=b.dataset.on!=='false';b.dataset.on=String(!on);b.querySelector('.sound-label').textContent=on?'SOUND OFF':'SOUND ON';b.querySelector('span').textContent=on?'♪':'♫';}});
function findPhone(el){return el.closest('.screen')?.id==='screen-pink'?'pink':'blue'}
document.addEventListener('submit',e=>{let f=e.target;if(!f.matches('[data-form]'))return;e.preventDefault();let phone=f.dataset.phone;let input=f.querySelector('input');if(f.dataset.form==='search'){let q=input.value.trim();if(!q)return;state.query[phone]=q;render(phone);if(q.toLowerCase().includes('signal')&&phone==='blue'&&state.quest===0)questComplete(0,'Signal found!');return}if(f.dataset.form==='map'){let q=input.value.trim().toLowerCase();if(q.includes('moonbean')||q.includes('cafe')||q.includes('café')){state.query[phone]='Moonbean Café';render(phone);if(state.connected&&phone==='pink'&&state.quest===1)questComplete(1,'Moonbean found!');}else{toast('Try searching for Moonbean Café');}return}if(f.dataset.form==='message'){let text=input.value.trim();if(!text)return;if(!state.connected){toast('Link the phones first to send a message!');return}state.messages.push({from:phone==='blue'?'Blue':'Pink',text,time:'9:41'});state.opened.blue='messages';state.opened.pink='messages';render('blue');render('pink');if(phone==='blue'&&text.toLowerCase().includes('moonlight')&&state.quest===2)questComplete(2,'Meetup code delivered!');else toast('Message sent to your partner!');}});
document.addEventListener('input',e=>{let n=e.target.closest('[data-note]');if(n){let p=n.dataset.note;state.note[p]=n.innerText; if(state.connected){let other=p==='blue'?'pink':'blue';state.note[other]=state.note[p];}}});
document.addEventListener('click',e=>{if(e.target.closest('[data-browser-refresh]'))toast('Page refreshed');});
$('#syncButton').addEventListener('click',link);
$('#soundToggle').addEventListener('click',e=>{let b=e.currentTarget;let on=b.dataset.on!=='false';b.dataset.on=String(!on);b.querySelector('.sound-label').textContent=on?'SOUND OFF':'SOUND ON';b.querySelector('span').textContent=on?'♪':'♫'});
render('blue');render('pink');updateQuest();

